1	/** Curated catalog of GX expectations the check editor exposes in v1. */
2	
3	import {
4	  DATASOURCE_CATEGORY,
5	  isFileDatasource,
6	  isSqlQueryable,
7	  runsSqlBatch,
8	  supportsMonitors,
9	  type ConnectionType,
10	} from '../../api/connections';
11	import { CUSTOM_SQL_EXPECTATION_TYPE, CUSTOM_SQL_QUERY_KEY } from './customSql';
12	
13	export type ConfigFieldType = 'string' | 'number' | 'list' | 'sql' | 'select' | 'boolean';
14	
15	/** The check `kind` (ADR 0012). `expectation` (incl. custom-SQL) is GX; the
16	 *  monitor kinds run a scalar SQL aggregate instead. Sent to the backend. */
17	export type CheckKind =
18	  'expectation' | 'freshness' | 'volume' | 'schema_drift' | 'anomaly' | 'comparison';
19	
20	/**
21	 * Expectation categories — the GX-Cloud-style classification the check editor groups by. v1 ships
22	 * value-level GX expectations + custom-SQL (ADR 0019) + the freshness/volume monitor kinds (ADR 00
23	 */
24	export type ExpectationCategory =
25	  | 'Column values'
26	  | 'Table shape'
27	  | 'Freshness'
28	  | 'Volume'
29	  | 'Schema'
30	  | 'Anomaly'
31	  | 'Custom SQL'
32	  | 'Comparison'
33	  | 'Snowflake DMF';
34	
35	/** Check engine (ADR 0036). */
36	export type CheckEngine = 'gx' | 'dmf';
37	
38	export const EXPECTATION_CATEGORIES: ExpectationCategory[] = [
39	  'Column values',
40	  'Table shape',
41	  'Freshness',
42	  'Volume',
43	  'Schema',
44	  'Snowflake DMF',
45	  'Anomaly',
46	  'Custom SQL',
47	  'Comparison',
48	];
49	
50	/** The canonical comparison expectation type (ADR 0015; `comparison:columns` stays reserved). */
51	export const COMPARISON_EXPECTATION_TYPE = 'comparison:records';
52	export const COMPARISON_COLUMNS_EXPECTATION_TYPE = 'comparison:columns';
53	
54	/**
55	 * Monitor categories (ADR 0012) — gated by `supportsMonitors` (below), which is BROADER than SQL-
56	 * queryable: Iceberg and flat files (adls_gen2/s3) also offer them.
57	 */
58	export const MONITOR_CATEGORIES: ExpectationCategory[] = ['Freshness', 'Volume'];
59	
60	/** The seven canonical DQ dimensions (ADR 0038) — the *semantic quality aspect* a check measures. */
61	export const DQ_DIMENSIONS = [
62	  'accuracy',
63	  'completeness',
64	  'consistency',
65	  'integrity',
66	  'timeliness',
67	  'uniqueness',
68	  'validity',
69	] as const;
70	
71	export type DqDimension = (typeof DQ_DIMENSIONS)[number];
72	
73	/** One-line "what does this dimension mean" help for the editor's select. */
74	export const DQ_DIMENSION_HELP: Record<DqDimension, string> = {
75	  accuracy: 'Does the data match reality / a trusted source?',
76	  completeness: 'Is all the expected data present?',
77	  consistency: 'Do related datasets agree with each other?',
78	  integrity: 'Do relationships between datasets hold?',
79	  timeliness: 'Is the data recent enough?',
80	  uniqueness: 'Are there unexpected duplicates?',
81	  validity: 'Does the data conform to its rules and formats?',
82	};
83	
84	/** Static display labels for the seven dimensions — a closed vocabulary needs no runtime
85	 *  capitalize helper (that duplicated across `checkBadges.tsx`/`ScorecardPanel.tsx` before). */
86	export const DIMENSION_LABEL: Record<DqDimension, string> = {
87	  accuracy: 'Accuracy',
88	  completeness: 'Completeness',
89	  consistency: 'Consistency',
90	  integrity: 'Integrity',
91	  timeliness: 'Timeliness',
92	  uniqueness: 'Uniqueness',
93	  validity: 'Validity',
94	};
95	
96	export interface ConfigField {
97	  /** Key in the GX `config` kwargs object. */
98	  name: string;
99	  label: string;
100	  type: ConfigFieldType;
101	  optional?: boolean;
102	  help?: string;
103	  /**
104	   * Inline STATIC bounds for a `number` field (the backend is authoritative — e.g. anomaly's
105	   * `window` is 3-90; #593).
106	   */
107	  min?: number;
108	  max?: number;
109	  /** Increment for a `number` field's stepper; the antd default of 1 is unusable on a 0–1 range. */
110	  step?: number;
111	  /** Value/label options for a `select` field. */
112	  options?: { value: string; label: string }[];
113	  /**
114	   * For a `number` field: an ADDITIONAL dynamic ceiling — this field's max is also capped by a
115	   * SIBLING config field's live value (read off the same `configValues` `showWhen` reads).
116	   */
117	  maxFrom?: string;
118	  /** Friendly name of the `maxFrom` field, for the validation message. */
119	  maxFromLabel?: string;
120	  /**
121	   * CREATE-mode pre-filled value, mirroring the backend's own default (e.g. anomaly's `window`
122	   * defaults to 14 server-side) so an untouched field submits the same value the backend would
123	   */
124	  defaultValue?: unknown;
125	  /**
126	   * Show (and submit) this field only when a SIBLING config field equals a given value — a generic
127	   * conditional-field mechanism.
128	   */
129	  showWhen?: { field: string; equals: unknown };
130	}
131	
132	/**
133	 * True when `field` should render/submit given the current sibling config values (see
134	 * `ConfigField.showWhen`).
135	 */
136	export function fieldVisible(
137	  field: ConfigField,
138	  configValues: Record<string, unknown> | undefined,
139	): boolean {
140	  if (!field.showWhen) return true;
141	  return (configValues ?? {})[field.showWhen.field] === field.showWhen.equals;
142	}
143	
144	/** Severity-threshold semantics for a monitor kind (ADR 0012/0016). */
145	export interface MonitorThresholdSpec {
146	  /** What the warn/fail/critical numbers mean for this kind. */
147	  help: string;
148	  /** Upper bound on the inputs (omit = unbounded, e.g. freshness age-hours). */
149	  max?: number;
150	  /** Require a fail or critical threshold (freshness has no in-config bound, so
151	   *  without one it can never fail — the #426 silent-green guard). */
152	  requireFailOrCritical?: boolean;
153	}
154	
155	export interface ExpectationSpec {
156	  /** snake_case GX expectation type (or `monitor:<kind>`) sent to the backend. */
157	  type: string;
158	  /** Check kind (ADR 0012); defaults to `expectation` when omitted. */
159	  kind?: CheckKind;
160	  label: string;
161	  description: string;
162	  category: ExpectationCategory;
163	  /** The DQ dimension this check type measures (ADR 0038) — the editor's derived default. */
164	  dimension?: DqDimension;
165	  fields: ConfigField[];
166	  /** Present for monitor kinds — drives the threshold block's help/bounds/required. */
167	  thresholds?: MonitorThresholdSpec;
168	  /** Engine (ADR 0036); omitted = `gx`. Fixed `dmf` for the `dmf:*` types below. */
169	  engine?: CheckEngine;
170	  /** `dmf:unique_count` degrades downward — the backend rejects any threshold on it. */
171	  noThresholds?: boolean;
172	  /**
173	   * GX has no SqlAlchemy metric provider for this type, so it errors on a SQL batch. Mirrors the
174	   * backend's `gx_runner.DATAFRAME_ONLY_EXPECTATION_TYPES`, which 422s it at author time — this
175	   * flag only keeps it out of the picker.
176	   */
177	  dataframeOnly?: boolean;
178	}
179	
180	/** Freshness's type — same string for both engines, so it's a choice rather than a second entry. */
181	export const FRESHNESS_EXPECTATION_TYPE = 'monitor:freshness';
182	
183	/** Mirrors `engines_for('snowflake')` (`backend/app/datasources/engines.py`). */
184	export function offersDmfEngine(connectionType: ConnectionType | undefined): boolean {
185	  return connectionType === 'snowflake';
186	}
187	
188	/** True only for Freshness on a Snowflake connection — the one spec with an engine choice. */
189	export function showEngineChoiceFor(
190	  spec: ExpectationSpec | undefined,
191	  connectionType: ConnectionType | undefined,
192	): boolean {
193	  return spec?.type === FRESHNESS_EXPECTATION_TYPE && offersDmfEngine(connectionType);
194	}
195	
196	/** The engine a check actually runs on. */
197	export function effectiveEngineFor(
198	  spec: ExpectationSpec | undefined,
199	  connectionType: ConnectionType | undefined,
200	  engineChoice: string | undefined,
201	): CheckEngine {
202	  if (spec?.engine) return spec.engine;
203	  if (showEngineChoiceFor(spec, connectionType)) return (engineChoice as CheckEngine) ?? 'gx';
204	  return 'gx';
205	}
